// tab-namer: renames the active tab with a short lowercase name joined by underscores
// (e.g. fix_login_api), generated by claude (haiku) from what is on the terminal screen.
// Opened with `mod.open:tab-namer`: it acts and closes itself.
import { View, div } from "gpui-kit";
import { focused, panes, spaces, run, exec, hc, props, closeOverlay, notify, home } from "herdr";

const MODEL = "haiku";
const MAX_CHARS = 24;
const MAX_WORDS = 3;

// Keeps only letters/digits, no accents, lowercase, joined with _ .
export function clean(text) {
  const words = (text ?? "")
    .split("\n")[0]
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .split("_")
    .filter(Boolean)
    .slice(0, MAX_WORDS);
  return words.join("_").slice(0, MAX_CHARS).replace(/_+$/, "");
}

// The terminal that gives context: the focused one, else the first agent, else the tab's first.
function terminalOf(tabId) {
  const f = focused();
  const inTab = panes().filter((p) => p.tab === tabId && p.terminal);
  return inTab.find((p) => p.pane === f?.pane) ?? inTab.find((p) => p.program?.agent) ?? inTab[0] ?? null;
}

async function nameTab() {
  const f = focused();
  if (!f?.tab) return notify({ title: "Name tab", body: "There is no active tab.", level: "warning" });
  const pane = terminalOf(f.tab);
  if (!pane) return notify({ title: "Name tab", body: "This tab has no terminal.", level: "warning" });

  const space = spaces().find((s) => s.tabs.some((t) => t.id === f.tab));
  notify({ title: "Naming tab…", body: space?.name ?? "", level: "info", timeout: 4000 });
  try {
    const screen = (await hc(["read", pane.terminal])).stdout.trim().split("\n").slice(-60).join("\n").slice(-3500);
    const prompt =
      `Give me a short name for a terminal tab, 1 to ${MAX_WORDS} words, lowercase, ` +
      `joined with underscores, no spaces or accents (example: fix_login_api). Reply with ONLY the name, nothing else.\n` +
      `Describe what the work is about, not the program.\n` +
      `Folder: ${pane.cwd ?? ""}\nSpace: ${space?.name ?? ""}\nTitle: ${pane.title ?? ""}\n` +
      `Terminal screen:\n${screen}`;
    // Closed stdin (</dev/null): otherwise claude waits 3 s for piped input.
    const r = await exec("sh", ["-c", 'claude -p --model "$1" "$2" </dev/null', "sh", MODEL, prompt], { cwd: home() });
    const name = clean(r.stdout);
    if (!name) throw new Error(r.stderr.trim().split("\n").pop() || "empty response");
    run("tab.rename", { id: f.tab, name });
    notify({ title: "Tab renamed", body: name, level: "success", timeout: 3000 });
  } catch (e) {
    notify({ title: "Couldn't name the tab", body: String(e?.message ?? e), level: "error" });
  }
}

export default class TabNamer extends View {
  init() {
    const overlay = props()?.overlay;
    nameTab().finally(() => overlay && closeOverlay(overlay));
  }
  render() {
    return div();
  }
}
